-- 📚 꼭집 주거 사전 — 소득 기준 밑값 · 공통 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-13 · 실행 2.1초 · 결과:
-- {"median": {"year": 2026, "rows": 8}, "urban": {"year": 2025, "rows": 8}, "basis_rows": 11, "anns": 268, "pct": [{"std": "국민임대", "pct": 70, "n": 79}, {"std": "국민임대", "pct": 150, "n": 9}, {"std": "매입임대", "pct": 100, "n": 32}, {"std": "매입임대", "pct": 70, "n": 24}, {"std": "매입임대", "pct": 130, "n": 20}, {"std": "매입임대", "pct": 50, "n": 3}, {"std": "영구임대", "pct": 50, "n": 21}, {"std": "영구임대", "pct": 70, "n": 18}, {"std": "영구임대", "pct": 100, "n": 16}, {"std": "통합공공임대", "pct": 150, "n": 4}, {"std": "행복주택", "pct": 100, "n": 21}, {"std": "행복주택", "pct": 110, "n": 3}, {"std": "행복주택", "pct": 120, "n": 3}], "ex": ["2015122300020816", "2015122300020793", "2015122300020792", "2015122300020788"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x order by x.announcement_id,(x.source='LH')desc,x.created_at desc),e as(select distinct ec.announcement_id,coalesce(m.std_type,ec.housing_type)std,ec.income_pct from eligibility_criteria ec join a on a.announcement_id=ec.announcement_id and a.yr=2026 left join housing_type_map m on m.source_table='eligibility_criteria' and m.housing_type=ec.housing_type where ec.announcement_id is not null)select json_build_object('median',(select json_build_object('year',max(standard_year),'rows',count(*)) from median_income_monthly),'urban',(select json_build_object('year',max(standard_year),'rows',count(*)) from urban_worker_monthly_income),'basis_rows',(select count(*) from eligibility_criteria where announcement_id is null),'anns',(select count(distinct announcement_id) from e),'pct',(select json_agg(json_build_object('std',std,'pct',income_pct,'n',n) order by std,n desc) from(select std,income_pct,count(distinct announcement_id)n from e where income_pct is not null group by 1,2)q where n>=3),'ex',(select json_agg(i) from(select distinct announcement_id i from e where std='국민임대' and income_pct=70 order by 1 desc limit 4)q))j;
